let bad! () =
  IO.println_err "N must be a whole number, 1 or more";
  Proc.exit 2

let run_from! k n =
  let r = $?(sh flaky.sh);
  if r.code == 0 then (
    IO.println "attempt %{k}: ok";
    IO.println "output: %{r.stdout}";
    0
  ) else (
    IO.println "attempt %{k}: exit %{r.code}";
    if k >= n then (
      IO.println "gave up after %{n} attempts";
      1
    ) else run_from! (k + 1) n
  )

let main! () =
  match Proc.args () with
  | [a] ->
    match Int.of_string a with
    | Ok n -> if n >= 1 then Proc.exit (run_from! 1 n) else bad! ()
    | Error _ -> bad! ()
  | _ -> bad! ()

main! ()
