let fail! code msg =
  IO.println_err msg;
  Proc.exit code

let run! root old new =
  let files = FS.glob_in ./**/*.txt root |> List.filter_map (fn p -> Path.relative_to root p |> Option.map (fn r -> (Path.to_string r, p)));
  let sorted = List.sort files;
  let results = List.filter_map (fn (rel, p) ->
    let text = FS.read_file! p;
    let n = List.length (String.split old text) - 1;
    if n > 0 then
      (FS.write_file! p (String.replace old new text); Some (rel, n))
    else None) sorted;
  List.each (fn (rel, n) -> IO.println "changed %{rel} (%{n})") results;
  let total = List.sum (List.map (fn (_, n) -> n) results);
  IO.println "changed %{List.length results} files, %{total} replacements"

let main! () =
  match Proc.args () with
  | dir :: old :: new :: _ ->
    if old == "" then fail! 2 "OLD must not be empty"
    else if !(FS.dir? (Path.of_string dir)) then fail! 1 "not a directory: %{dir}"
    else run! (Path.of_string dir) old new
  | _ -> fail! 2 "usage: prog DIR OLD NEW"

main! ()
EOF
