import List
import Proc

let fail code msg =
  IO.println_err msg;
  Proc.exit code

let run dir old new =
  let root = Path.of_string dir;
  let rels = List.filter_map (fn p -> Path.relative_to root p) (FS.glob_in ./**/*.txt root);
  let names = List.sort (List.map Path.to_string rels);
  let results = List.filter_map (fn name ->
    let path = Path.join root (Path.of_string name);
    let text = FS.read_file! path;
    let parts = String.split old text;
    let n = List.length parts - 1;
    if n > 0 then
      (FS.write_file! path (String.join new parts); Some (name, n))
    else None) names;
  List.each (fn (name, n) -> IO.println "changed %{name} (%{n})") results;
  let total = List.sum (List.map (fn (_, n) -> n) results);
  IO.println "changed %{List.length results} files, %{total} replacements"

let main () =
  match Proc.args () with
  | dir :: old :: new :: _ ->
    if old == "" then fail 2 "OLD must not be empty"
    else if !(FS.dir? (Path.of_string dir)) then fail 1 "not a directory: %{dir}"
    else run dir old new
  | _ -> fail 2 "usage: DIR OLD NEW"

main ()
